from lib import R
BF = "73-breakfast-world.txt"; SL = "74-salads-more.txt"
B = [
 ("Savory Oatmeal with Fried Egg", "International", 5, 10, 2, "Breakfast", "100 g|rolled oats; 400 ml|water; 2|eggs; 2|green onions, sliced; 1 tbsp|soy sauce; 1 tsp|sesame oil; 1 tbsp|vegetable oil; |black pepper", "Simmer the oats in the salted water for 5 minutes until creamy / Fry the eggs in the oil until the edges crisp / Spoon the oats into bowls, top with the eggs and green onions and drizzle with soy sauce and sesame oil"),
 ("Tofu Breakfast Tacos", "Tex-Mex", 10, 10, 4, "Breakfast, Brunch", "400 g|firm tofu, crumbled; 0.5 tsp|turmeric; 1 tsp|cumin; 1|onion, diced; 8|corn tortillas; 1|avocado, sliced; 120 ml|salsa; 2 tbsp|olive oil; |salt", "Soften the onion in the oil over medium heat for 5 minutes / Add the tofu, turmeric, cumin and salt and cook 5 minutes until hot and lightly golden / Warm the tortillas and fill with the tofu, avocado and salsa"),
 ("Chickpea Flour Omelette", "Indian", 10, 10, 2, "Breakfast, Brunch", "100 g|chickpea flour; 180 ml|water; 0.25 tsp|turmeric; 0.5 tsp|baking powder; 0.5|onion, finely chopped; 1|tomato, diced; 1 handful|cilantro; 1|green chili, opt; 2 tbsp|vegetable oil; |salt", "Whisk the chickpea flour, water, turmeric, baking powder and salt to a smooth batter and rest 5 minutes / Stir in the onion, tomato, cilantro and chili / Pour half into a hot oiled frying pan, cook 3 minutes, flip and cook 2 minutes; repeat"),
 ("Huevos Divorciados", "Mexican", 10, 15, 2, "Breakfast, Brunch", "4|eggs; 4|corn tortillas; 120 ml|salsa verde; 120 ml|salsa roja; 200 g|refried beans; 30 g|queso fresco; 2 tbsp|vegetable oil", "Warm the beans and the two salsas in separate pans / Lightly fry the tortillas in the oil and lay two on each plate / Fry the eggs and set two on each plate / Spoon green salsa over one egg and red over the other, add beans and crumble over the cheese"),
 ("Turkish Eggs with Garlic Yogurt (Cilbir)", "Turkish", 10, 10, 2, "Breakfast, Brunch", "250 g|greek yogurt; 1 clove|garlic, grated; 4|eggs; 40 g|butter; 1 tsp|aleppo pepper; 1 tbsp|white vinegar; 1 handful|dill; 2 slices|bread, toasted; |salt", "Stir the garlic and salt into the yogurt and spread over two plates / Poach the eggs in simmering water with the vinegar for 3 to 4 minutes / Melt the butter with the aleppo pepper until foaming / Set the eggs on the yogurt, spoon over the butter, scatter with dill and serve with toast"),
 ("Mushroom and Thyme Toast", "British", 10, 10, 2, "Breakfast, Brunch, Lunch", "250 g|mushrooms, sliced; 2 tbsp|butter; 1 clove|garlic; 1 tsp|thyme; 2 slices|sourdough bread; 2 tbsp|cream cheese; 1 tsp|lemon juice; |salt", "Cook the mushrooms in the butter over high heat for 6 to 8 minutes until browned / Add the garlic, thyme, salt and lemon juice / Toast the bread, spread with cream cheese and pile the mushrooms on top"),
 ("Breakfast Burrito Bowls", "Tex-Mex", 10, 20, 4, "Breakfast, Brunch", "400 g|potatoes, diced; 6|eggs; 1 can|black beans, drained; 1|red bell pepper, diced; 60 g|cheddar, grated; 120 ml|salsa; 1|avocado; 2 tbsp|olive oil; 1 tsp|chili powder; |salt", "Fry the potatoes in the oil with the chili powder and salt over medium heat for 15 minutes, adding the pepper for the last 5 / Warm the beans / Scramble the eggs softly / Divide into bowls and top with cheese, salsa and avocado"),
 ("Pumpkin Spice Oatmeal", "American", 5, 10, 2, "Breakfast", "100 g|rolled oats; 350 ml|milk; 120 g|pumpkin puree; 2 tbsp|maple syrup; 1 tsp|pumpkin pie spice; 30 g|pecans, chopped", "Simmer the oats in the milk for 5 minutes, stirring / Stir in the pumpkin, maple syrup and spice and heat through / Serve topped with pecans"),
 ("Ham and Cheese Croissant Bake", "French", 15, 35, 6, "Breakfast, Brunch", "6|croissants, torn; 200 g|ham, diced; 120 g|gruyere, grated; 5|eggs; 400 ml|milk; 1 tsp|dijon mustard; |black pepper", "Butter a baking dish and scatter in the croissants, ham and most of the cheese / Whisk the eggs, milk, mustard and pepper, pour over and leave 15 minutes / Top with the rest of the cheese and bake at 180 °C (350 °F) for 30 to 35 minutes until set"),
 ("Cinnamon French Toast Casserole", "American", 15, 45, 8, "Breakfast, Brunch", "1 loaf|brioche, cubed; 6|eggs; 500 ml|milk; 80 g|brown sugar; 2 tsp|cinnamon; 1 tsp|vanilla extract; 50 g|butter, melted; |maple syrup", "Put the bread in a buttered dish / Whisk the eggs, milk, half the sugar, cinnamon and vanilla, pour over and chill at least 1 hour or overnight / Drizzle with the butter, sprinkle with the remaining sugar and bake at 175 °C (350 °F) for 40 to 45 minutes / Serve with maple syrup"),
 ("Egg and Vegetable Breakfast Fried Rice", "Chinese", 10, 10, 2, "Breakfast, Lunch", "400 g|cooked rice, cold; 3|eggs; 100 g|frozen peas; 2|green onions; 2 tbsp|soy sauce; 1 tsp|sesame oil; 2 tbsp|vegetable oil", "Scramble the eggs in half the oil in a hot wok and set aside / Stir-fry the peas in the rest of the oil for 2 minutes, then add the rice and toss over high heat for 4 minutes / Return the eggs with the soy sauce, sesame oil and green onions"),
 ("Sweet Potato Toast with Almond Butter", "American", 5, 15, 2, "Breakfast, Snack", "1|sweet potato, large; 3 tbsp|almond butter; 1|banana, sliced; 1 tsp|cinnamon; 1 tbsp|honey", "Cut the sweet potato lengthways into 1 cm slices / Toast them in a toaster on high for 3 or 4 cycles, or roast at 200 °C (400 °F) for 15 minutes, until tender / Spread with almond butter and top with banana, cinnamon and honey"),
 ("Banana Bread Overnight Oats", "American", 5, 0, 2, "Breakfast", "100 g|rolled oats; 240 ml|milk; 120 g|greek yogurt; 1|banana, mashed; 1 tbsp|maple syrup; 0.5 tsp|cinnamon; 30 g|walnuts, chopped", "Mix the oats, milk, yogurt, banana, maple syrup and cinnamon in two jars / Chill overnight / Top with walnuts before eating"),
 ("Savory Cottage Cheese Bowl", "American", 5, 0, 1, "Breakfast, Lunch", "200 g|cottage cheese; 6|cherry tomatoes, halved; 0.5|cucumber, diced; 1 tbsp|olive oil; 1 tsp|everything bagel seasoning; |black pepper", "Spoon the cottage cheese into a bowl / Top with the tomatoes and cucumber / Drizzle with oil and sprinkle with seasoning and pepper"),
 ("Green Shakshuka", "Middle Eastern", 10, 20, 4, "Breakfast, Brunch, Dinner", "1|leek, sliced; 200 g|spinach; 200 g|kale, chopped; 1|zucchini, diced; 2 cloves|garlic; 1 tsp|cumin; 6|eggs; 80 g|feta; 2 tbsp|olive oil; |salt", "Soften the leek and zucchini in the oil over medium heat for 6 minutes / Add the garlic, cumin, kale and spinach and cook until wilted / Make 6 hollows, crack in the eggs, cover and cook on low for 6 to 8 minutes / Crumble over the feta"),
 ("Spinach and Cheese Breakfast Strata", "American", 20, 50, 8, "Breakfast, Brunch", "8 slices|bread, cubed; 200 g|spinach, wilted and squeezed; 150 g|cheddar, grated; 8|eggs; 500 ml|milk; 1 tsp|dijon mustard; |salt", "Layer the bread, spinach and cheese in a buttered dish / Whisk the eggs, milk, mustard and salt and pour over; chill at least 2 hours / Bake at 175 °C (350 °F) for 45 to 50 minutes until puffed and set"),
 ("Kaya Toast with Soft Eggs", "Singaporean", 5, 10, 2, "Breakfast", "4 slices|white bread; 4 tbsp|kaya, coconut jam; 30 g|butter, cold, thinly sliced; 4|eggs; 1 tbsp|soy sauce; |white pepper", "Lower the eggs into boiling water, turn off the heat, cover and leave 6 minutes / Toast the bread, spread with kaya and sandwich with thin slices of butter / Crack the eggs into bowls and season with soy sauce and pepper to dip"),
 ("Egg Bhurji (Indian Scrambled Eggs)", "Indian", 10, 10, 2, "Breakfast, Brunch", "4|eggs; 1|onion, finely chopped; 1|tomato, chopped; 1|green chili; 0.25 tsp|turmeric; 0.5 tsp|garam masala; 1 handful|cilantro; 1 tbsp|butter; |salt", "Soften the onion in the butter for 5 minutes, then add the chili, tomato, turmeric and salt and cook 3 minutes / Add the beaten eggs and stir over low heat until softly set / Finish with garam masala and cilantro and serve with flatbread or toast"),
 ("Tamago Kake Gohan (Egg over Rice)", "Japanese", 2, 0, 1, "Breakfast", "200 g|cooked rice, hot; 1|egg, very fresh; 2 tsp|soy sauce; 1|green onion, sliced; 1 pinch|furikake", "Put the steaming rice in a bowl and make a well / Crack in the egg, add the soy sauce and stir quickly so the heat of the rice lightly cooks the egg / Top with green onion and furikake; use only very fresh, high-quality eggs as the egg stays partly raw"),
 ("Rava Upma", "South Indian", 10, 15, 3, "Breakfast", "180 g|semolina; 1|onion, chopped; 1 tsp|mustard seeds; 1 tbsp|urad dal, opt; 10|curry leaves; 1|green chili; 1 tsp|ginger, grated; 600 ml|water; 2 tbsp|ghee; 1 handful|cilantro; |salt", "Toast the semolina in a dry pan until fragrant and set aside / Fry the mustard seeds, dal and curry leaves in the ghee until they crackle, then the onion, chili and ginger for 4 minutes / Add the water and salt and bring to a boil, then rain in the semolina while stirring and cook 2 to 3 minutes / Cover off the heat for 2 minutes and finish with cilantro"),
 ("Tex-Mex Migas", "Tex-Mex", 10, 10, 2, "Breakfast, Brunch", "4|corn tortillas, cut in strips; 4|eggs; 0.5|onion, diced; 1|jalapeno, diced; 1|tomato, diced; 40 g|cheddar, grated; 2 tbsp|vegetable oil; |salt", "Fry the tortilla strips in the oil until crisp and set aside / Soften the onion and jalapeno 3 minutes, add the tomato / Add the beaten eggs and the strips and stir until softly set / Top with the cheese"),
 ("Onion Uttapam", "South Indian", 10, 20, 4, "Breakfast", "600 ml|dosa batter, store-bought or homemade; 2|onions, finely chopped; 2|tomatoes, finely chopped; 1|green chili, chopped; 1 handful|cilantro; 2 tbsp|vegetable oil", "Heat a lightly oiled frying pan over medium heat / Spread a ladle of batter into a thick 15 cm round / Scatter with onion, tomato, chili and cilantro and press in lightly / Drizzle with oil, cook 3 minutes, flip and cook 2 minutes; repeat"),
]
for t, cu, p, c, s, meals, ings, steps in B: R(BF, t, "Breakfast", cu, p, c, s, meals, ings, steps)
S = [
 ("Broccoli Crunch Salad with Bacon", "American", 15, 5, 6, "Salad, Side dish, Lunch", "500 g|broccoli, small florets; 6 slices|bacon, cooked and crumbled; 40 g|dried cranberries; 40 g|sunflower seeds; 0.5|red onion, finely diced; 120 g|mayonnaise; 1 tbsp|apple cider vinegar; 1 tbsp|honey", "Whisk the mayonnaise, vinegar and honey / Toss with the broccoli, onion, cranberries and seeds / Chill 30 minutes and top with the bacon"),
 ("Japanese Cucumber Sunomono", "Japanese", 10, 0, 4, "Salad, Side dish", "2|cucumbers, very thinly sliced; 1 tsp|salt; 4 tbsp|rice vinegar; 1 tbsp|sugar; 1 tsp|soy sauce; 1 tbsp|sesame seeds; 1 tbsp|wakame, soaked, opt", "Toss the cucumber with the salt, leave 10 minutes and squeeze dry / Stir the vinegar, sugar and soy sauce until the sugar dissolves / Toss with the cucumber and wakame and sprinkle with sesame"),
 ("Endive, Pear and Blue Cheese Salad", "French", 10, 0, 4, "Salad, Appetizer", "3|endives, leaves separated; 1|pear, sliced; 60 g|blue cheese; 40 g|walnuts, toasted; 2 tbsp|olive oil; 1 tbsp|white wine vinegar; 1 tsp|honey; |salt", "Whisk the oil, vinegar, honey and salt / Arrange the endive and pear on a platter / Scatter with crumbled cheese and walnuts and drizzle with the dressing"),
 ("Roasted Sweet Potato and Kale Salad", "American", 15, 25, 4, "Salad, Lunch", "2|sweet potatoes, cubed; 200 g|kale, chopped; 1 can|chickpeas, drained; 40 g|pumpkin seeds; 3 tbsp|olive oil; 2 tbsp|tahini; 1|lemon; 1 tsp|maple syrup; |salt", "Roast the sweet potato and chickpeas with 2 tbsp oil and salt at 210 °C (410 °F) for 25 minutes / Massage the kale with the rest of the oil and a pinch of salt / Whisk the tahini, lemon juice, maple syrup and water to a pourable dressing / Toss everything together and scatter with seeds"),
 ("Carrot Ginger Sesame Salad", "Asian", 10, 0, 4, "Salad, Side dish", "400 g|carrots, julienned; 1 tbsp|ginger, grated; 2 tbsp|rice vinegar; 1 tbsp|soy sauce; 1 tbsp|sesame oil; 1 tsp|honey; 1 tbsp|sesame seeds; 1 handful|cilantro", "Whisk the ginger, vinegar, soy sauce, sesame oil and honey / Toss with the carrots / Sprinkle with sesame seeds and cilantro"),
 ("Classic Tuna Salad", "American", 10, 0, 3, "Salad, Lunch", "2 cans|tuna, drained; 80 g|mayonnaise; 1|celery stalk, finely diced; 0.25|red onion, finely diced; 1 tbsp|lemon juice; 1 tbsp|pickle relish; |black pepper", "Flake the tuna into a bowl / Mix in the mayonnaise, celery, onion, lemon, relish and pepper / Serve on lettuce, crackers or in sandwiches"),
 ("Beef Taco Salad", "Tex-Mex", 15, 10, 4, "Salad, Lunch, Dinner", "400 g|ground beef; 2 tbsp|taco seasoning; 1|romaine lettuce, chopped; 200 g|cherry tomatoes; 1 can|black beans, drained; 80 g|cheddar, grated; 100 g|tortilla chips; 120 g|sour cream; 120 ml|salsa", "Brown the beef with the taco seasoning and a splash of water / Divide the lettuce, tomatoes and beans between bowls / Top with the beef, cheese and broken chips / Thin the sour cream with the salsa and spoon over"),
 ("Corn and Tomato Salad with Basil", "American", 10, 5, 4, "Salad, Side dish", "4|corn cobs, kernels cut off; 300 g|cherry tomatoes, halved; 0.5|red onion, thinly sliced; 1 handful|basil; 2 tbsp|olive oil; 1 tbsp|red wine vinegar; |salt", "Blanch the corn kernels for 2 minutes and cool, or use raw if very fresh / Toss with the tomatoes, onion, oil, vinegar and salt / Tear in the basil just before serving"),
 ("Spinach Salad with Warm Bacon Dressing", "American", 10, 10, 4, "Salad, Side dish", "200 g|baby spinach; 6 slices|bacon, chopped; 2|eggs, hard-boiled; 150 g|mushrooms, sliced; 0.5|red onion, sliced; 3 tbsp|red wine vinegar; 1 tsp|dijon mustard; 1 tsp|sugar", "Fry the bacon until crisp, lift out and keep 3 tbsp of the fat in the pan / Whisk the vinegar, mustard and sugar into the warm fat / Toss the spinach, mushrooms and onion with the warm dressing and top with bacon and sliced egg"),
 ("Grilled Halloumi and Watermelon Salad", "Cypriot", 10, 5, 4, "Salad, Lunch", "250 g|halloumi, sliced; 600 g|watermelon, cubed; 1|cucumber, sliced; 1 handful|mint; 2 tbsp|olive oil; 1|lime", "Grill or fry the halloumi in a dry pan for 1 to 2 minutes per side until golden / Toss the watermelon, cucumber and mint with the oil and lime juice / Top with the warm halloumi"),
 ("Burrata with Heirloom Tomatoes", "Italian", 10, 0, 4, "Salad, Appetizer", "2|burrata; 600 g|tomatoes, mixed, sliced; 1 handful|basil; 3 tbsp|olive oil; 1 tbsp|balsamic vinegar; |flaky salt", "Arrange the tomatoes on a platter and season with salt / Set the burrata in the middle and tear it open / Drizzle with oil and balsamic and scatter with basil; serve with bread"),
 ("Shaved Brussels Sprout Salad", "American", 15, 0, 4, "Salad, Side dish", "400 g|brussels sprouts, finely shaved; 40 g|parmesan, shaved; 40 g|almonds, toasted; 30 g|dried cranberries; 3 tbsp|olive oil; 1|lemon; 1 tsp|dijon mustard; |salt", "Whisk the oil, lemon juice, mustard and salt / Toss with the shaved sprouts and leave 10 minutes to soften / Add the parmesan, almonds and cranberries"),
 ("Edamame and Corn Salad", "Asian", 10, 5, 4, "Salad, Side dish, Lunch", "300 g|edamame, shelled; 200 g|corn kernels; 1|red bell pepper, diced; 2|green onions; 2 tbsp|rice vinegar; 1 tbsp|soy sauce; 1 tbsp|sesame oil; 1 tsp|honey", "Cook the edamame and corn 3 minutes and cool under cold water / Whisk the vinegar, soy, oil and honey / Toss with the vegetables"),
 ("Roasted Beet and Orange Salad", "Mediterranean", 15, 50, 4, "Salad, Side dish", "4|beets; 2|oranges, segmented; 100 g|arugula; 60 g|goat cheese; 30 g|pistachios; 2 tbsp|olive oil; 1 tbsp|sherry vinegar; |salt", "Wrap the beets in foil and roast at 200 °C (400 °F) for 45 to 50 minutes until tender; cool, peel and slice / Whisk the oil, vinegar and salt / Arrange the arugula, beets and oranges and top with cheese and pistachios; drizzle with dressing"),
 ("Celery, Apple and Walnut Salad", "American", 10, 0, 4, "Salad, Side dish", "4|celery stalks, thinly sliced; 2|apples, thinly sliced; 50 g|walnuts, toasted; 40 g|parmesan, shaved; 2 tbsp|olive oil; 1|lemon; 1 handful|parsley; |salt", "Toss the celery and apple with the lemon juice straight away so the apple stays pale / Add the oil, salt, parsley and walnuts / Top with the parmesan"),
 ("Radish and Cucumber Yogurt Salad", "Eastern European", 10, 0, 4, "Salad, Side dish", "200 g|radishes, sliced; 1|cucumber, sliced; 200 g|greek yogurt; 1 handful|dill; 1 clove|garlic, grated; 1 tbsp|lemon juice; |salt", "Stir the garlic, lemon and salt into the yogurt / Fold in the radishes and cucumber / Scatter with dill and serve cold"),
 ("Asparagus and Egg Salad", "French", 10, 10, 4, "Salad, Appetizer, Lunch", "500 g|asparagus; 4|eggs; 2 tbsp|olive oil; 1 tbsp|white wine vinegar; 1 tsp|dijon mustard; 1 tbsp|capers; 1 handful|chives; |salt", "Boil the eggs 9 minutes, cool and chop / Blanch the asparagus 2 to 3 minutes and cool in iced water / Whisk the oil, vinegar, mustard and salt / Arrange the asparagus, scatter with egg, capers and chives and dress"),
 ("Quinoa Kale Salad with Lemon", "American", 15, 15, 4, "Salad, Lunch", "180 g|quinoa; 150 g|kale, finely chopped; 1 can|chickpeas, drained; 60 g|feta; 30 g|dried cranberries; 3 tbsp|olive oil; 1|lemon; |salt", "Rinse the quinoa and simmer in 400 ml salted water for 15 minutes; cool / Massage the kale with 1 tbsp oil and salt / Toss everything with the rest of the oil and the lemon juice and zest"),
 ("Chopped Antipasto Salad", "Italian-American", 15, 0, 4, "Salad, Lunch", "1|romaine lettuce, chopped; 80 g|salami, chopped; 100 g|mozzarella, diced; 100 g|chickpeas; 60 g|pepperoncini; 60 g|black olives; 150 g|cherry tomatoes; 3 tbsp|olive oil; 1 tbsp|red wine vinegar; 1 tsp|oregano", "Whisk the oil, vinegar and oregano / Chop everything into small even pieces / Toss with the dressing just before serving"),
 ("Smoked Mackerel and Potato Salad", "Scandinavian", 15, 15, 4, "Salad, Lunch", "600 g|new potatoes; 200 g|smoked mackerel, flaked; 4|radishes, sliced; 120 g|sour cream; 1 tbsp|horseradish; 1 tbsp|lemon juice; 1 handful|dill", "Boil the potatoes 15 minutes, drain and halve / Mix the sour cream, horseradish and lemon / Toss the warm potatoes with the dressing, then fold in the mackerel, radishes and dill"),
]
for t, cu, p, c, s, meals, ings, steps in S: R(SL, t, "Salad", cu, p, c, s, meals, ings, steps)
